import test from 'node:test';
import assert from './assert.mjs';
import {readFile} from 'node:fs/promises';
import {JSDOM} from 'jsdom';
import {act,createElement as h,createRef,StrictMode} from 'react';
import {renderToString} from 'react-dom/server';
import {userEvent} from '@testing-library/user-event';
import {MerchantListingBlock} from '@dmf-ui/react';
import {ListingProof,renderListing} from '../.test-dist/server.mjs';
const items=[{id:'a',name:'Sample A'},{id:'b',name:'Sample B'}],base={id:'listing',title:'Sample listings',items,getItemKey:item=>item.id,renderItem:item=>h('a',{href:'#'+item.id},item.name)};

test('packed listing has semantic results, validates identity and hides stale content in nonready states',()=>{
 const dom=new JSDOM(renderToString(h(MerchantListingBlock,{...base,description:'Authored description',pagination:h('nav',{'aria-label':'Pages'},h('a',{href:'#next'},'Next'))})));
 try{const d=dom.window.document;assert.equal(d.querySelector('section').getAttribute('aria-labelledby'),'listing-title');assert.equal(d.querySelector('#listing-title').tagName,'H2');assert.equal(d.querySelector('ul').children.length,2);assert.equal(d.querySelector('section').getAttribute('aria-describedby'),'listing-description');assert(d.querySelector('nav'));}finally{dom.window.close();}
 for(const status of ['loading','error']){let calls=0;const dom=new JSDOM(renderToString(h(MerchantListingBlock,{...base,status,getItemKey:()=>{calls++;throw Error('stale key');},renderItem:()=>{calls++;throw Error('stale render');},pagination:h('nav',{},'Should be absent')})));try{const d=dom.window.document;assert.equal(calls,0);assert.equal(d.querySelector('ul,nav'),null);if(status==='loading'){assert.equal(d.querySelector('[aria-busy=true]').contains(d.querySelector('[role=status]')),false);assert.equal(d.querySelector('[role=status]').textContent,'Loading merchants…');assert.equal(d.querySelector('[aria-hidden=true]').querySelector('a,button,input'),null);}else assert(d.querySelector('[role=alert]'));}finally{dom.window.close();}}
 const empty=new JSDOM(renderToString(h(MerchantListingBlock,{...base,items:[],emptyTitle:'Tidak ada contoh hasil'})));try{assert(empty.window.document.body.textContent.includes('Tidak ada contoh hasil'));assert.equal(empty.window.document.querySelector('[role=alert],ul'),null);}finally{empty.window.close();}
 for(const bad of [[{id:'a'},{id:'a'}],[{id:' '}],[{id:4}]])assert.throws(()=>renderToString(h(MerchantListingBlock,{...base,items:bad})),/unique nonempty/);
 assert.throws(()=>renderToString(h(MerchantListingBlock,{...base,status:'empty'})),/unsupported/);
});

async function withDOM(html,run){const dom=new JSDOM(`<div id="root">${html}</div>`,{url:'https://consumer.test/listing.html'}),saved=new Map(),warnings=[],old=console.error;for(const key of ['window','document','HTMLElement','navigator','IS_REACT_ACT_ENVIRONMENT']){saved.set(key,Object.getOwnPropertyDescriptor(globalThis,key));Object.defineProperty(globalThis,key,{configurable:true,writable:true,value:key==='IS_REACT_ACT_ENVIRONMENT'?true:dom.window[key]});}console.error=(...args)=>warnings.push(args.join(' '));const roots=[];try{const {createRoot,hydrateRoot}=await import('react-dom/client');await run({dom,user:userEvent.setup({document}),mount:async element=>{const root=createRoot(document.querySelector('#root'));roots.push(root);await act(async()=>root.render(element));return root;},hydrate:async()=>{let root;await act(async()=>{root=hydrateRoot(document.querySelector('#root'),h(StrictMode,{},h(ListingProof)),{identifierPrefix:'listing-',onRecoverableError:e=>warnings.push(String(e))});});roots.push(root);return root;}});assert.deepEqual(warnings,[]);}finally{await act(async()=>{for(const root of roots)root.unmount();});console.error=old;dom.window.close();for(const [key,value]of saved){if(value)Object.defineProperty(globalThis,key,value);else delete globalThis[key];}}}

test('packed listing hydrates and stable keys preserve item DOM/state across host reordering',()=>withDOM(renderListing(),async({hydrate,user})=>{
 const original=document.querySelector('[data-sample-key=sample-cafe]');await hydrate();assert.equal(document.querySelector('[data-sample-key=sample-cafe]'),original);const ids=[...document.querySelectorAll('[id]')].map(e=>e.id);assert.equal(new Set(ids).size,ids.length);
 const note=original.querySelector('input');await act(async()=>user.type(note,'Host-owned note'));
 await act(async()=>user.click([...document.querySelectorAll('button')].find(b=>b.textContent==='Reverse sample order')));assert.equal(document.querySelector('[data-sample-key=sample-cafe]'),original);assert.equal(note.value,'Host-owned note');assert.equal(document.querySelector('.dmf-listing-grid > li:first-child [data-slot=card]').dataset.sampleKey,'sample-kitchen');
 await act(async()=>user.selectOptions(document.querySelector('[data-listing-language]'),'id'));assert.equal(document.querySelector('#consumer-listing-title').textContent,'Daftar contoh merchant');assert.equal(document.querySelector('#consumer-independent-title').textContent,'Independent empty listing');
 await act(async()=>user.selectOptions(document.querySelector('[data-listing-state]'),'error'));assert.equal(document.querySelector('#consumer-listing ul'),null);const retry=[...document.querySelectorAll('button')].find(b=>b.textContent==='Kembali ke data contoh');await act(async()=>user.click(retry));assert(document.querySelector('#consumer-listing ul'));assert.equal(document.activeElement,document.querySelector('[data-listing-state]'));
 await act(async()=>user.selectOptions(document.querySelector('[data-listing-count]'),'empty'));assert.equal(document.querySelector('#consumer-listing nav'),null);assert(document.querySelector('#consumer-listing').textContent.includes('Tidak ada contoh hasil'));
}));

test('bare packed listing forwards the section ref, supports custom state content and cleans up',()=>withDOM('',async({mount})=>{const ref=createRef();const root=await mount(h(MerchantListingBlock,{...base,ref,status:'loading',loadingContent:h('p',{},'Custom loading'),statusMessage:'Host update'}));assert.equal(ref.current.tagName,'SECTION');assert.equal(document.querySelector('[role=status]').textContent,'Host update');assert(document.body.textContent.includes('Custom loading'));await act(async()=>root.render(h(MerchantListingBlock,{...base,items:[],emptyContent:h('p',{},'Custom empty'),ref})));assert(document.body.textContent.includes('Custom empty'));await act(async()=>root.render(null));assert.equal(ref.current,null);}));

test('production listing exposes native links and content before hydration',async()=>{const dom=new JSDOM(await readFile('dist/listing.html','utf8'));try{const d=dom.window.document;assert.equal(d.querySelector('#consumer-listing ul').children.length,3);assert(d.querySelector('#consumer-listing a[href="#sample-cafe"]'));assert(d.querySelector('#sample-cafe'));assert.equal(d.querySelector('[data-listing-state]').disabled,true);assert.equal(d.querySelector('#consumer-listing a').hasAttribute('aria-disabled'),false);}finally{dom.window.close();}});
